{
  "requirement_items": [
    {
      "section": "4.2.3.7.6",
      "label": "[REQ-1-OAD-1485]",
      "text": "Access to all required instrument locations for regular servicing and maintenance shall be provided via walkways, elevators, lifts and stairs.",
      "id": "REQ-1-OAD-1485"
    },
    {
      "section": "4.2.3.7.6",
      "label": "",
      "text": "Sufficient space shall be provided for personnel and the required equipment to access the service locations.",
      "id": null
    },
    {
      "section": "4.2.3.7.7",
      "label": "[REQ-1-OAD-1490]",
      "text": "Walkway access must be provided between the -X and +X Nasmyth platforms.",
      "id": "REQ-1-OAD-1490"
    },
    {
      "section": "4.2.3.7.7",
      "label": "",
      "text": "The walkway must be accessible at all telescope elevation angles.",
      "id": null
    },
    {
      "section": "4.2.3.7.7",
      "label": "[REQ-1-OAD-1492]",
      "text": "The walkways between the +X and -X Nasmyth areas shall be >1.5 m wide.",
      "id": "REQ-1-OAD-1492"
    },
    {
      "section": "4.2.3.7.8",
      "label": "[REQ-1-OAD-1500]",
      "text": "The Nasmyth platform infrastructure, combined with the enclosure crane, shall provide for the safe installation, handling and removal of instrument components up to TBD size and TBD mass.",
      "id": "REQ-1-OAD-1500"
    },
    {
      "section": "4.2.3.7.8",
      "label": "[REQ-1-OAD-1505]",
      "text": "The size and volume limit for lifting instrument components is defined by the capacity of the enclosure crane.",
      "id": "REQ-1-OAD-1505"
    },
    {
      "section": "4.2.3.7.8",
      "label": "",
      "text": "Instrument assembly procedures must not rely on the use of the enclosure crane for extended periods of time.",
      "id": null
    },
    {
      "section": "4.2.3.7.8",
      "label": "",
      "text": "As a goal, no instrument AIV plan shall require the use of the observatory crane for more than TBD hours per day, for more than TBD days total.",
      "id": null
    },
    {
      "section": "4.2.3.7.8",
      "label": "[REQ-1-OAD-1510]",
      "text": "Instrument teams may elect to temporarily use their own smaller cranes, lifts etc., on the Nasmyth platforms for the assembly of instruments.",
      "id": "REQ-1-OAD-1510"
    },
    {
      "section": "4.2.3.7.8",
      "label": "[REQ-1-OAD-1515]",
      "text": "A lay down area for staging and assembly of equipment shall be provided on at least one Nasmyth platform.",
      "id": "REQ-1-OAD-1515"
    },
    {
      "section": "4.2.3.7.8",
      "label": "",
      "text": "This area will be used for unpacking and assembly of instrument components prior to lifting them into place at the instrument location.",
      "id": null
    },
    {
      "section": "4.2.3.7.8",
      "label": "",
      "text": "The lay down area shall have a footprint of at least 5 x 7 m, and shall be located such that a temporary clean room, up to 5 m high, can be assembled above it, to create environmental conditions suitable for handling precision mechanisms and optics.",
      "id": null
    },
    {
      "section": "4.2.3.7.8",
      "label": "",
      "text": "As a goal, this area will be equipped as permanent instrument lab where entire instruments can be assembled and then lifted to their final location.",
      "id": null
    },
    {
      "section": "4.2.3.7.8",
      "label": "[REQ-1-OAD-1517]",
      "text": "The telescope STR design shall provide sufficient clearance between it and the enclosure fixed base and rotating base to allow a component of the size shown in the figure below to be lifted from the floor to the Nasmyth platforms.",
      "id": "REQ-1-OAD-1517"
    },
    {
      "section": "4.2.3.7.8",
      "label": "[REQ-1-OAD-1520]",
      "text": "Instruments shall be designed in a manner such that a temporary clean and controlled environment can be provided for assembling an instrument in-situ.",
      "id": "REQ-1-OAD-1520"
    },
    {
      "section": "4.2.3.7.8",
      "label": "",
      "text": "All Nasmyth instrument handling, installation and removal activities shall be compatible with the requirements of the operating observatory environment.",
      "id": null
    },
    {
      "section": "4.2.3.7.8",
      "label": "",
      "text": "Activities such as welding, cutting and grinding are considered incompatible with this environment and must be avoided in all circumstances.",
      "id": null
    },
    {
      "section": "4.2.3.7.8",
      "label": "",
      "text": "Activities shall be planned, and equipment shall be designed in such a manner that any damage to the telescope optics is highly unlikely.",
      "id": null
    },
    {
      "section": "4.2.3.7.8",
      "label": "[REQ-1-OAD-1530]",
      "text": "The Nasmyth platforms shall be designed in such a way as to enable the addition of new instruments without affecting the productivity of the already commissioned instrument suite.",
      "id": "REQ-1-OAD-1530"
    },
    {
      "section": "4.2.3.7.9",
      "label": "[REQ-1-OAD-1535]",
      "text": "Servicing equipment required for regular use, including platform lifts, small cranes, personnel lifts, vacuum pumps, tool cabinets, workbenches, shall be stored on the Nasmyth platforms.",
      "id": "REQ-1-OAD-1535"
    },
    {
      "section": "4.2.3.7.10",
      "label": "[REQ-1-OAD-1540]",
      "text": "Allowance shall be made for 21 m2 of floor space with at least 3 m overhead clearance on the -X platform for instrument electronics, equipment and tools.",
      "id": "REQ-1-OAD-1540"
    },
    {
      "section": "4.2.3.7.10",
      "label": "[REQ-1-OAD-1555]",
      "text": "Allowance shall be made for 38 m2 of floor space with at least 2.5 m overhead clearance on the +X platform for instrument electronics, equipment and tools.",
      "id": "REQ-1-OAD-1555"
    },
    {
      "section": "4.2.3.7.11",
      "label": "[REQ-1-OAD-1570]",
      "text": "An escape system shall be provided to allow personnel to exit the Nasmyth Platforms in the case of emergency.",
      "id": "REQ-1-OAD-1570"
    },
    {
      "section": "4.2.3.7.11",
      "label": "[REQ-1-OAD-1575]",
      "text": "As a goal, a personnel refuge and rest area shall be provided on each of the +X and -X Nasmyth platforms.",
      "id": "REQ-1-OAD-1575"
    },
    {
      "section": "4.2.3.7.11",
      "label": "[REQ-1-OAD-1580]",
      "text": "Elevators for access to the Nasmyth areas shall be designed such that safety is achieved through design for minimum risk, and with the incorporation of automatic safety devices where necessary.",
      "id": "REQ-1-OAD-1580"
    },
    {
      "section": "4.2.3.7.11",
      "label": "[REQ-1-OAD-1585]",
      "text": "Areas on the telescope or enclosure where personnel need to work frequently at a height more than 1.8 meters above the observing floor shall be equipped with safety rails having kick plates to prevent loose items from being kicked over the edge.",
      "id": "REQ-1-OAD-1585"
    }
  ],
